import * as React from 'react'
import { useDispatch } from 'react-redux'
import { getMe } from './redux/authentication'

// ** Router Import
import Router from './router/Router'

const App = () => {
  const dispatch = useDispatch()
  React.useEffect(() => {
    dispatch(getMe())
  }, [])
  return (
    <React.Suspense fallback={null}>
      <Router />
    </React.Suspense>
  )
}

export default App
