// ** Redux Imports
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit'


// ** Axios Imports
import axios, { AxiosRequestConfig, AxiosRequestHeaders }  from 'axios'

export const getAllData = createAsyncThunk('appStaffs/getAllData', async () => {
  const response = await axios.get('/api/v1/user?skip=0&order_by=id%20DESC')
  console.log("all data: ", response.data)
  return response.data
})

export const getData = createAsyncThunk('appStaffs/getData', async params => {
  const response = await axios.get('/api/v1/user', {params})
  // console.log('data: ', response.data)
  return {
    params,
    data: response.data,
    totalPages: response.data.page_total
  }
})

export const getStaff = createAsyncThunk('appStaffs/getUser', async id => {
  // console.log(id)
  const params = {
    user_id: id
  }
  const response = await axios.get('/api/v1/user/user', {params})
  // console.log(response)
  return response.data
})

export const addStaff = createAsyncThunk('appStaffs/addStaff', async (staff, { dispatch, getState }) => {
  // console.log(staff)
  await axios.post('/api/v1/auth/register', staff)
  await dispatch(getData(getState().staffs.params))
  await dispatch(getAllData())
  return staff
})

